<!doctype html><html lang="ja"><head><meta charset="utf-8"><title>入金管理</title><style>body{font-family:"Noto Sans JP",Meiryo,sans-serif;background:#f3f6fa;margin:0;padding:18px}.panel{background:#fff;border:1px solid #d9e2ee;border-radius:8px;padding:14px;margin-bottom:12px}.row{display:grid;grid-template-columns:1fr 150px 150px 150px auto;gap:8px}input,select,button{font:inherit;padding:8px;border:1px solid #cbd7e6;border-radius:6px}button{background:#0b6ff6;color:#fff;border-color:#0b6ff6}.table{width:100%;border-collapse:collapse}.table th,.table td{border-bottom:1px solid #edf1f6;padding:8px;text-align:left;font-size:13px}.msg{background:#e9f8ef;color:#137333;padding:10px;border-radius:6px;margin-bottom:12px}</style></head><body>@if(session('status'))<div class="msg">{{ session('status') }}</div>@endif @if($errors->any())<div class="msg" style="background:#fff1f0;color:#b42318">@foreach($errors->all() as $error)<div>{{ $error }}</div>@endforeach</div>@endif <div class="panel"><h1>入金登録</h1><form method="post" action="{{ route('retail.payments.store') }}">@csrf<div class="row"><select name="retail_customer_id" required><option value="">顧客</option>@foreach($customers as $customer)<option value="{{ $customer->id }}">{{ $customer->customer_code }} / {{ $customer->name }}</option>@endforeach</select><input type="date" name="payment_date" value="{{ now()->toDateString() }}" required><select name="payment_method"><option value="cash">現金</option><option value="bank_transfer">振込</option><option value="card">カード</option><option value="qr">QR</option><option value="other">その他</option></select><input name="amount" type="number" min="1" step="1" placeholder="入金額" required><button>入金登録</button></div></form></div><div class="panel"><h2>入金一覧</h2><table class="table"><thead><tr><th>番号</th><th>入金日</th><th>顧客</th><th>金額</th><th>未充当</th><th></th></tr></thead><tbody>@foreach($payments as $payment)<tr><td>{{ $payment->payment_no }}</td><td>{{ $payment->payment_date->format('Y-m-d') }}</td><td>{{ $payment->customer?->name }}</td><td>¥{{ number_format((float)$payment->amount) }}</td><td>¥{{ number_format((float)$payment->unapplied_amount) }}</td><td><a href="{{ route('retail.payments.show',$payment) }}">表示</a></td></tr>@endforeach</tbody></table>{{ $payments->links() }}</div></body></html>

